INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9002000', '2022年11月30日ChatGPT横空出世', '2022年11月30日ChatGPT横空出世', '产品发布', '2022-11-30', '2022年11月30日，OpenAI CEO在推特写下：“今天我们推出了ChatGPT，尝试在这里与它谈。”链接一点，免费聊天入口就此敞开。ChatGPT本质是一个大型语言模型，能模仿人类语调、回答问题、撰写文案，甚至充当写作导师。它不局限于话题，从AI伦理到旅行攻略都能即兴输出，让“与机器人闲聊”第一次有了真实温度。', '[]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007001', '2026-04-19-claude-opus-4-7', 'Claude Opus 4.7 正式发布：比聪明更重要的，是靠谱', '产品发布', '2026-04-19', 'Anthropic发布Claude Opus 4.7模型，在AI模型可靠性上取得重大突破。编程基准测试中表现优异，超越GPT-5.4和Gemini 3.1 Pro；新增2576像素长边识别能力提升视觉推理；任务韧性显著增强，能自主绕过工具链崩溃障碍。', '[{"title":"Anthropic 官方新闻","url":"https://www.anthropic.com/news"},{"title":"Claude 产品页面","url":"https://www.anthropic.com/claude"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007002', '2026-04-19-qwen3-6-35b-a3b', '阿里开源 Qwen3.6-35B-A3B：30亿激活参数实现编程能力跨越式升级', '产品发布', '2026-04-19', '阿里巴巴千问团队开源稀疏混合专家（MoE）模型Qwen3.6-35B-A3B，总参数量350亿，激活参数仅30亿。编程能力超越270亿参数稠密模型，支持思维链保留，已集成至Qwen Studio并通过阿里云百炼平台提供API服务。', '[{"title":"QwenLM GitHub","url":"https://github.com/QwenLM/Qwen3"},{"title":"Hugging Face 模型页","url":"https://huggingface.co/Qwen"},{"title":"阿里云百炼平台","url":"https://bailian.console.aliyun.com/"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007003', '2026-04-19-openai-codex-update', 'OpenAI更新Codex：支持Mac桌面操控、多智能体并行与长期任务执行', '产品发布', '2026-04-19', 'OpenAI对Codex进行重大更新，新增Mac桌面应用操控能力、多智能体并行运行功能，以及记忆功能实现长期任务执行与工作流无缝恢复，同时优化浏览器体验和插件生态。', '[{"title":"OpenAI Codex","url":"https://openai.com/index/introducing-codex/"},{"title":"OpenAI API 文档","url":"https://platform.openai.com/docs"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007004', '2026-04-19-opera-browser-connector', 'Opera 推出浏览器连接器功能，让AI聊天机器人无缝集成', '产品发布', '2026-04-19', 'Opera推出"浏览器连接器"功能，基于MCP协议建立AI模型与外部数据源的安全双向连接。用户可在浏览器中集成ChatGPT、Claude等AI工具，适用于Opera One和Opera GX。', '[{"title":"Opera 官方博客","url":"https://blogs.opera.com/"},{"title":"Opera Browser Connector","url":"https://www.opera.com/features/browser-connector"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007005', '2026-04-19-nvidia-lyra2-0', '英伟达发布 Lyra2.0：单照生成90米3D环境，多项指标超越竞争对手', '产品发布', '2026-04-19', '英伟达发布Lyra2.0技术，通过单张照片生成90米范围的高连贯性3D虚拟环境，解决传统视频模型的空间失真与误差累积问题，可与物理引擎无缝衔接，为机器人仿真训练提供支持。', '[{"title":"NVIDIA 开发者博客","url":"https://developer.nvidia.com/blog/"},{"title":"NVIDIA Omniverse","url":"https://www.nvidia.com/en-us/omniverse/"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007006', '2026-04-19-gemini-personal-photos', '谷歌Gemini接入个人相册，AI生成图像迈向真正个性化', '产品发布', '2026-04-19', '谷歌Gemini接入个人相册，通过Nano Banana工具可直接调取Google Photos中的私人相片，无需手动上传，打通私人影像与AI生成能力之间的壁垒，实现真正意义上的个性化图像生成。', '[{"title":"Google AI Blog","url":"https://blog.google/technology/ai/"},{"title":"Google Gemini","url":"https://gemini.google.com/"},{"title":"Google Photos","url":"https://photos.google.com/"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007007', '2026-04-19-perplexity-mac-assistant', 'Perplexity推出Mac端AI助手：7×24小时运行，可代用户操作电脑', '产品发布', '2026-04-19', 'Perplexity推出Mac端AI助手Personal Computer，支持文本与语音交互，可直接访问文件系统和原生应用，实时感知用户活跃窗口并主动提供操作建议。所有操作在隔离的安全沙箱中完成，保障用户隐私。', '[{"title":"Perplexity AI","url":"https://www.perplexity.ai/"},{"title":"Perplexity Mac App","url":"https://www.perplexity.ai/download/mac"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007008', '2026-04-19-ios27-ai-features', '拍照即录入、标签自动起名！iOS27四大AI升级曝光，重塑iPhone交互日常', '产品发布', '2026-04-19', '苹果iOS 27 Beta版本揭示多项Apple Intelligence新功能：营养标签解析（自动扫描食品数据同步至健康应用）、纸面信息识别（提取电话号码/地址至通讯录）、实体卡券数字化扫描、智能标签组命名。', '[{"title":"Apple Intelligence","url":"https://www.apple.com/apple-intelligence/"},{"title":"Apple Newsroom","url":"https://www.apple.com/newsroom/"}]');